refentry.refsect1:
&reftitle.description;
inttidy_config_count tidytidy
tidy_config_count retourne le nombre d'erreurs rencontrées dans la configuration de l'objet tidy Tidy spécifié.

  &reftitle.examples;



    Exemple avec tidy_config_count


<?php
$html = '<p>test</I>';

// Depuis PHP 8.5.0, une valeur invalide dans un tableau de configuration
// lève une TypeError ; la valeur invalide est donc lue depuis un fichier
// de configuration
$configFile = tempnam(sys_get_temp_dir(), 'tidy');
file_put_contents($configFile, "wrap: abc\n");

$tidy = tidy_parse_string($html, $configFile);

/* Affichera 1, car 'abc' n'est pas une valeur valide pour wrap */
echo tidy_config_count($tidy);

unlink($configFile);
?>


    &example.outputs.similar;


Notice: tidy_parse_string(): There were errors while parsing the Tidy configuration file "/tmp/tidyAbC123" in %s on line %d
